      project(fullPath: $fullPath) {
        incidentManagementTimelineEvents(incidentId: $incidentId) {
          nodes {
            id
            note
            noteHtml
            action
            occurredAt
            createdAt
            timelineEventTags {
              nodes {
                id
                name
              }
            }
          }
        }
      }
    }

